-- =====================================================================
--  Lumenvale Water · Network Operations — demo database
--  A fictional municipal water utility. Every name and number here is
--  synthetic and generated by 02_seed.sql.
--
--  Model: a small "historian" (sensors + readings) like most SCADA
--  systems expose, plus asset tables, billing and an alarm log.
-- =====================================================================

CREATE SCHEMA IF NOT EXISTS ops;
SET search_path TO ops, public;

-- ---------------------------------------------------------------------
-- Assets
-- ---------------------------------------------------------------------
CREATE TABLE reservoir (
    reservoir_id   text PRIMARY KEY,           -- 'RSV-01'
    name           text NOT NULL,
    capacity_m3    numeric NOT NULL,
    low_level_pct  numeric NOT NULL,            -- operating band
    high_level_pct numeric NOT NULL
);

CREATE TABLE dma (                              -- District Metered Area
    dma_id            text PRIMARY KEY,         -- 'DMA-N1'
    name              text NOT NULL,
    connections       int  NOT NULL,
    baseline_mnf_m3h  numeric NOT NULL          -- expected minimum night flow
);

CREATE TABLE pump_station (
    station_id     text PRIMARY KEY,            -- 'PS-01'
    name           text NOT NULL,
    rated_flow_m3h numeric NOT NULL,
    pumps          int NOT NULL
);

-- ---------------------------------------------------------------------
-- Historian
-- ---------------------------------------------------------------------
CREATE TABLE sensor (
    sensor_id  int  PRIMARY KEY,
    tag        text UNIQUE NOT NULL,            -- 'RSV-01.LEVEL'
    kind       text NOT NULL,                   -- level | flow | power | pressure | chlorine | status
    unit       text NOT NULL,
    asset_type text NOT NULL,                   -- reservoir | dma | pump_station | plant | zone
    asset_id   text NOT NULL
);

CREATE TABLE reading (
    ts        timestamptz NOT NULL,
    sensor_id int NOT NULL REFERENCES sensor (sensor_id),
    value     double precision NOT NULL,
    PRIMARY KEY (sensor_id, ts) DEFERRABLE   -- deferrable: shift_to_now() moves all rows at once
);
CREATE INDEX reading_ts_idx ON reading (ts);
-- With TimescaleDB: SELECT create_hypertable('ops.reading', 'ts');

-- ---------------------------------------------------------------------
-- Billing (daily billed volume per DMA, from smart meters)
-- ---------------------------------------------------------------------
CREATE TABLE billed_daily (
    day       date NOT NULL,
    dma_id    text NOT NULL REFERENCES dma (dma_id),
    billed_m3 numeric NOT NULL,
    PRIMARY KEY (dma_id, day) DEFERRABLE
);

-- ---------------------------------------------------------------------
-- Alarm log
-- ---------------------------------------------------------------------
CREATE TABLE alarm (
    alarm_id   serial PRIMARY KEY,
    raised_at  timestamptz NOT NULL,
    cleared_at timestamptz,                     -- NULL = still active
    severity   text NOT NULL CHECK (severity IN ('critical', 'major', 'minor')),
    asset_id   text NOT NULL,
    message    text NOT NULL
);
CREATE INDEX alarm_raised_idx ON alarm (raised_at);
